(()=>{const get=id=>document.getElementById(id),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let tab='bookings',records=[],feedback=[];
async function request(path,options={}){const r=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});let d;try{d=await r.json();}catch{throw Error('Could not reach customer records. Please sign in again.');}if(!r.ok)throw Error(d.error||'Could not save.');return d;}
const panel=window.customerAdmin={active:false,async load(){get('admin-error').textContent='';try{if(tab==='bookings')records=(await request('/api/admin/bookings')).bookings;else feedback=(await request('/api/admin/feedback')).feedback;panel.render();}catch(e){get('admin-error').textContent=e.message;}},render(){get('add-button').hidden=true;get('page-title').textContent=tab==='bookings'?'Bookings & customers.':'Reviews & feedback.';get('page-subtitle').textContent=tab==='bookings'?'Review requests, contact customers and manage private documents.':'Publish approved reviews and read private customer feedback.';get('fleet-search').placeholder='Search by name, phone or message';get('save-info').textContent='Customer details and documents are restricted to owner access.';document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('selected'));document.querySelectorAll('[data-customer-view]').forEach(b=>b.classList.toggle('selected',b.dataset.customerView===tab));const term=get('fleet-search').value.toLowerCase();const list=(tab==='bookings'?records:feedback).filter(r=>JSON.stringify(r).toLowerCase().includes(term));get('owner-content').innerHTML=list.length?list.map(r=>tab==='bookings'?`<article class="account-card"><div class="booking-top"><h2>${escape(r.name)}</h2><span class="booking-status">${escape(r.status)}</span></div><div class="booking-details"><span>Age ${r.age}<br><a href="tel:${escape(r.phone.replace(/[^+0-9]/g,''))}">${escape(r.phone)}</a><br>${escape(r.email)}</span><span>${escape(r.car_name)} · ${escape(r.location)}<br>${r.mode==='self'?'Self-drive':'Chauffeur'}<br>${escape(r.start_date)} to ${escape(r.end_date)}</span><span>Requested ${escape(new Date(r.created_at).toLocaleString())}<br>Reference ${escape(r.id.slice(0,8))}</span></div><label>Booking status<select data-booking-status="${escape(r.id)}">${['requested','confirmed','completed','cancelled'].map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label><p>Confirm only after checking the car is available and agreeing the price with the customer. This does not reserve stock automatically.</p>${r.documents.length?r.documents.map(d=>`<div class="document-row"><strong>${d.kind==='licence'?'Driving licence':'Masked Aadhaar'}</strong><a href="/api/admin/documents/${escape(d.id)}" target="_blank" rel="noopener">View private image</a><button class="secondary" data-delete-document="${escape(d.id)}">Delete image</button></div>`).join(''):'<p>No identity images uploaded.</p>'}</article>`:`<article class="account-card"><div class="booking-top"><h2>${r.kind==='review'?'Review · '+escape(r.display_name):'Private feedback'}</h2><span class="booking-status">${escape(r.status)}</span></div><p>${r.kind==='review'?'★'.repeat(r.rating)+' · ':''}${escape(r.email)} · ${escape(new Date(r.created_at).toLocaleString())}</p><p style="white-space:pre-wrap">${escape(r.message)}</p><label>${r.kind==='review'?'Review visibility':'Feedback status'}<select data-feedback-status="${escape(r.id)}">${(r.kind==='review'?['pending','approved','hidden']:['pending','resolved']).map(s=>`<option ${s===r.status?'selected':''}>${s}</option>`).join('')}</select></label>${r.kind==='review'?'<p>Only approved reviews show the display name, rating and message on the customer website. Check that the text contains no personal documents or identity numbers before approving.</p>':'<p>This message is never included in public reviews.</p>'}</article>`).join(''):'<div class="admin-empty">'+(term?'No matching records.':tab==='bookings'?'No booking requests yet.':'No reviews or feedback yet.')+'</div>';}};
document.querySelectorAll('[data-customer-view]').forEach(b=>b.onclick=()=>{panel.active=true;tab=b.dataset.customerView;get('fleet-search').value='';get('owner-content').textContent='Loading customer records…';panel.load();});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>document.querySelectorAll('[data-customer-view]').forEach(x=>x.classList.remove('selected'))));
get('refresh').addEventListener('click',()=>{if(panel.active)panel.load();});
get('owner-content').addEventListener('change',async e=>{const booking=e.target.dataset.bookingStatus,feedback=e.target.dataset.feedbackStatus;if(!booking&&!feedback)return;e.target.disabled=true;try{await request('/api/admin/'+(booking?'bookings/':'feedback/')+(booking||feedback),{method:'PUT',body:JSON.stringify({status:e.target.value})});await panel.load();}catch(err){get('admin-error').textContent=err.message;e.target.disabled=false;}});
get('owner-content').addEventListener('click',async e=>{const button=e.target.closest('[data-delete-document]');if(!button||!confirm('Permanently delete this identity image?'))return;try{await request('/api/admin/documents/'+button.dataset.deleteDocument,{method:'DELETE'});await panel.load();}catch(err){get('admin-error').textContent=err.message;}});
})();
